// Game-owned status/art: derives guidance only from visible/scanned state, never solution paths.
export function circuitStatus(m){const letters='ABCDEF',pairs=m.level.pairs.map(p=>({letter:letters[p.id],done:m.connected.has(p.id)}));const active=m.active?'Connecting '+letters[m.active.pair]+(Number.isFinite(m.active.deadline)?' · '+Math.max(0,(m.active.deadline-m.clock)/1000).toFixed(1)+'s left':''):m.done?'All circuits powered':'Start at a solid letter; finish at its matching ring';return{pairs,active};}
export function circuitStatusHTML(m){const s=circuitStatus(m);return `<div class="circuit-connections">${s.pairs.map(p=>`<span class="${p.done?'powered':''}">${p.letter} ${p.done?'✓':'○'}</span>`).join('')}</div><p>${s.active}</p>`;}
export function robotStep(m,p){if(!p.scanned)return{tool:'scan',text:'Unidentified component · scan first'};if(p.fixed)return{tool:null,text:'Repair complete'};if(m.mode==='diagnosis')return{tool:'scan',text:'Diagnosed'};switch(p.type){case 'motor':return !p.disconnected?{tool:'wire',text:'Disconnect motor wire'}:!p.removed?{tool:'wrench',text:'Release motor'}:!p.placed?{tool:'assembly',text:'Fit replacement motor'}:{tool:'wire',text:'Reconnect motor terminals'};case 'wheel':case 'arm':return !p.removed?{tool:'wrench',text:'Loosen '+p.type}: {tool:'assembly',text:'Fit replacement '+p.type};case 'gear':return{tool:'gear',text:p.placed?'Rotate notch to the upper gold mark':'Drag a gear from the tray'};case 'battery':return{tool:'battery',text:'Match voltage, then drag from tray'};case 'sensor':return{tool:'assembly',text:'Drag sensor from assembly tray'};case 'wire':return{tool:'wire',text:'Connect cyan terminal to gold'};case 'circuit':return{tool:'solder',text:'Trace the highlighted zigzag left to right'};case 'dirty':return{tool:'brush',text:'Scrub back and forth'};default:return{tool:'screw',text:'Tighten component screw clockwise'};}}
export function robotWorkflow(m){if(m.complete)return 'Test passed. Ready for the next job!';if(m.testing)return 'Test '+(m.testStage+1)+' / 3 · tap the illuminated control';const scanned=m.parts.filter(p=>p.scanned).length,fixed=m.parts.filter(p=>p.fixed).length;if(scanned<m.parts.length)return 'Diagnose · scan '+(m.parts.length-scanned)+' remaining component(s)';if(m.mode==='diagnosis')return 'All faults diagnosed · choose TEST ROBOT';if(fixed<m.parts.length&&!m.panelOpen)return m.screws.some(s=>s.turn>.02)?'Access · loosen the four case screws counterclockwise':'Access · choose OPEN PANEL';if(fixed<m.parts.length)return 'Repair · follow each scanned component’s next step';if(m.panelOpen)return 'Secure · close the panel';if(m.screws.some(s=>s.turn<.98))return 'Secure · tighten all four case screws clockwise';return 'Verify · choose TEST ROBOT, then controls 1 → 2 → 3';}
export function robotStatusHTML(m){return `<strong>${robotWorkflow(m)}</strong><div class="robot-job-counts">Diagnosed ${m.parts.filter(p=>p.scanned).length}/${m.parts.length} · Repaired ${m.parts.filter(p=>p.fixed).length}/${m.parts.length} · ${m.panelOpen?'Panel open':'Panel closed'}</div><div class="robot-job-parts" tabindex="0" role="region" aria-label="Component repair steps">${m.parts.map((p,i)=>{const step=robotStep(m,p);return `<span>${i+1}. ${p.scanned?p.type.toUpperCase():'UNKNOWN'} · ${step.text}</span>`;}).join('')}</div>`;}
export const ROBOT_TOOL_HINTS={scan:'Tap a flashing component to diagnose it. Scanning does not repair it.',screw:'Turn case screws counterclockwise to open; clockwise to secure. Loose component screws tighten clockwise.',wrench:'Rotate around a released component. Disconnect motor wires first.',wire:'Motor: disconnect before removal. Repaired parts: drag cyan terminal to gold.',gear:'Drag from the tray into the socket, then rotate the notch upward.',solder:'Trace highlighted circuit points from left to right.',brush:'Scrub a diagnosed dirty component back and forth.',battery:'Choose the socket voltage, then drag a battery from the lower-left tray.',assembly:'Drag a replacement from the lower-left tray after removing the old component.'};
export function drawWorkshopBackdrop(c){const g=c.createLinearGradient(0,0,0,640);g.addColorStop(0,'#253645');g.addColorStop(1,'#405659');c.fillStyle=g;c.fillRect(0,0,1000,640);for(const x of [25,835]){c.fillStyle='#1e303b';c.beginPath();c.roundRect(x,125,140,350,14);c.fill();for(let i=0;i<7;i++)for(let j=0;j<4;j++){c.fillStyle='#77939045';c.beginPath();c.arc(x+22+j*30,150+i*45,2,0,Math.PI*2);c.fill();}for(let i=0;i<3;i++){c.strokeStyle=['#98b2ac','#d0bc8e','#a6aac6'][i];c.lineWidth=5;c.beginPath();c.moveTo(x+25+i*40,190);c.lineTo(x+25+i*40,260+i*20);c.stroke();}}c.fillStyle='#756855';c.fillRect(0,618,1000,22);c.fillStyle='#baaa8644';c.fillRect(0,619,1000,3);}
export function drawBoardFrame(c,g){const {x,y,size}=g;c.fillStyle='#17353c';c.beginPath();c.roundRect(x-6,y-6,size+12,size+12,10);c.fill();c.strokeStyle='#86a8a477';c.lineWidth=2;c.stroke();for(const [sx,sy]of [[x-2,y-2],[x+size+2,y-2],[x-2,y+size+2],[x+size+2,y+size+2]]){c.fillStyle='#b0b8a8';c.beginPath();c.arc(sx,sy,3,0,Math.PI*2);c.fill();}c.strokeStyle='#b3956330';c.lineWidth=1;for(let i=1;i<9;i++){c.beginPath();c.moveTo(x+size*i/9,y);c.lineTo(x+size*i/9,y+size);c.stroke();}}
